# ==== .MainWindow.button_sync_effect_Clicked (linha 21566)
self.fan_config_dan_widget.hide()
for i, btn in enumerate(self.rgb_fan_shiyin_buttons):
    self.rgb_fan_shiyin_buttons[i].setIcon(QIcon(port.file_path_img(port.file_path_img(self.rgb_fan_shiyin_img[i]))))
    self.rgb_fan_shiyin_buttons[i].setChecked(False)

self.fan_tongping_button.setIcon(QIcon(port.file_path_img("img/fantasy1.svg")))
test.fan_shiyin_event.set()
test.fan_tongping_event.set()
time.sleep(0.1)
self.sync_effect_sender = self.sender()
if self.sync_effect_sender.isChecked():
    index = self.ARGB_SYNC_buttons.index(self.sync_effect_sender)
    self.fan_sync_no = index + 1
    print(f"Button {index} is checked")
    for button in self.ARGB_SYNC_buttons:
        if button is not self.sync_effect_sender:
            button.setChecked(False)
        else:
            self.ARGB_SYNC_buttons[index].setIcon(QIcon(port.file_path_img(port.file_path_img(self.SYNC_img_xuanzhong[index]))))

    for i, btn in enumerate(self.ARGB_SYNC_buttons):
        if i != index:
            self.ARGB_SYNC_buttons[i].setIcon(QIcon(port.file_path_img(port.file_path_img(self.SYNC_img[i]))))

    if self.fan_sync_all == 1:
        agreement.ARGB_SYNC_effect_NO(port.ARGB_ser, index)
    if self.fan_ten_stata != 0:
        agreement.fan_order_list[0] = index
        agreement.ARGB_ten_effect(port.ARGB_ser, 0, self.fan_ten_stata - 1)
# ==== .MainWindow.kaiguandeng_clicked (linha 21730)
if state:
    self.overlay.hide()
    self.kaiguandeng_lable_txt.setText(self.kaiguan_flag_light[0])
    self.kaiguandeng_lable_txt.setStyleSheet(f"\n            background-color: rgba(255, 255, 255, 0);\n            color: {port.lable_yanse};\n            font-size: 16px;                                                                                \n            ")
    port.fan_advanced_effect[13] = 0
    if port.fan_argb_button_model_index == 1:
        vaule_argb = port.fan_advanced_effect[0]
        if vaule_argb == 1:
            port.fan_advanced_effect[1] = 0
        self.fan_effect_speed_buttons[vaule_argb].click()
        self.tongbu_dengguang_on_off.show()
        self.tongbu_dengguang_on_off_switch.show()
        self.tongbu_dengguang_on_off_lable.show()
        self.kaiguandeng_shuxian.show()
else:
    self.overlay.show()
    self.overlay.raise_()
    self.kaiguandeng_lable_txt.setText(self.kaiguan_flag_light[1])
    self.kaiguandeng_lable_txt.setStyleSheet("\n            background-color: rgba(255, 255, 255, 0);\n            color: rgba(255, 255, 255, 153);\n            font-size: 16px; \n                                                                                                \n            ")
    port.fan_advanced_effect[13] = 1
    port.MCU_C_FLAG[0] = 0
    time.sleep(0.01)
    agreement.ARGB_MCU_C_changer(port.ARGB_ser, 1)
    agreement.argb_fan_light_off(port.ARGB_ser)
    self.tongbu_dengguang_on_off.hide()
    self.tongbu_dengguang_on_off_switch.hide()
    self.tongbu_dengguang_on_off_lable.hide()
    self.kaiguandeng_shuxian.hide()
    self.tongbu_dengguang_on_off_lable.setText(self.kaiguan_flag[1])
    self.tongbu_dengguang_on_off_lable.setStyleSheet("\n            background-color: rgba(255, 255, 255, 0);\n            color: rgba(255, 255, 255, 153);\n            font-size: 16px; \n                                                                                                \n            ")
    self.tongbu_dengguang_on_off_switch.setChecked(False)
port.argb_jiyi_write()
self.del_mouse_event()
# ==== .MainWindow.light_on_off_button_clicked (linha 21896)
if test.fan_shiyin_event.is_set():
    print("拾音同屏线程未在运行")
else:
    print("拾音同屏线程正在运行，正在停止")
    test.fan_shiyin_event.set()
    time.sleep(0.01)
if state:
    print("开关已打开")
    port.FAN_LIGHT_FLAG = 1
    self.fan_dengxiao_index()
else:
    print("开关已关闭")
    port.FAN_LIGHT_FLAG = 0
    if port.fan_argb_button_model_index == 3:
        time.sleep(0.01)
    agreement.argb_fan_light_off(port.ARGB_ser)
    self.chuji_effect_widget.hide()
    self.main_widget_mubu.hide()
